#!/usr/bin/env python3

with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

lines = content.split('\n')
sequences = []
current_seq = []

for line in lines:
    if line.strip():
        words = line.strip().split()
        sequences.append(words)

# Look for repeated patterns of 3 or more words
common_sequences = {}
for seq in sequences:
    for i in range(len(seq)-2):
        pattern = ' '.join(seq[i:i+3])
        if pattern not in common_sequences:
            common_sequences[pattern] = 0
        common_sequences[pattern] += 1

print("Most common 3-word sequences:")
for pattern, count in sorted(common_sequences.items(), key=lambda x: x[1], reverse=True)[:10]:
    if count > 1:
        print(f"Count {count}: {pattern}")

# Check for line repetitions
print("\nRepeated lines:")
line_counts = {}
for line in lines:
    if line.strip():
        if line not in line_counts:
            line_counts[line] = 0
        line_counts[line] += 1

for line, count in sorted(line_counts.items(), key=lambda x: x[1], reverse=True):
    if count > 1:
        print(f"Count {count}: {line[:50]}...")

#!/usr/bin/env python3

with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

words = content.split()
lengths = set(len(word) for word in words)

print(f"Unique word lengths found: {sorted(lengths)}")

# Show distribution of lengths
length_dist = {}
for word in words:
    l = len(word)
    if l not in length_dist:
        length_dist[l] = 0
    length_dist[l] += 1

print("\nLength distribution:")
for length, count in sorted(length_dist.items()):
    print(f"Length {length}: {count} words")

#!/usr/bin/env python3

def find_unique_variations(content):
    unique_words = set(content.split())
    print(f"Number of unique variations: {len(unique_words)}")
    print("\nUnique variations:")
    for word in sorted(unique_words):
        print(word)

def look_for_special_sequences(content):
    lines = content.split('\n')
    total_lines = len([l for l in lines if l.strip()])

    print(f"\nTotal lines in script: {total_lines}")

    # Look for potential control flow markers
    print("\nPotential control flow patterns:")
    for i, line in enumerate(lines):
        if line.strip():
            # Check for lines that might indicate jumps or branches
            if len(line.split()) >= 3:
                print(f"Line {i+1}: {line[:50]}...")

with open('/home/ctfplayer/ctf_files/banana.script', 'r') as f:
    content = f.read()

find_unique_variations(content)
look_for_special_sequences(content)

